  ) INTO v_metrics
  FROM public.onyx_snapshot_rows r
  WHERE r.snapshot_id=v_snapshot.id AND r.organization_id=v_org;

  SELECT coalesce(jsonb_agg(jsonb_build_object('status',x.status,'count',x.row_count) ORDER BY x.status),'[]'::jsonb)
    INTO v_distribution
